question:
Write a C# program to remove all adjacent duplicates from a string.

Input:
string str = "azxxzy";

response:
using System;

class Program
{
    static void Main()
    {
        string str = "azxxzy";
        string result = RemoveAdjacentDuplicates(str);
        Console.WriteLine(result); // azxy
    }

    static string RemoveAdjacentDuplicates(string str)
    {
        char[] arr = str.ToCharArray();
        int i = 0;
        for (int j = 1; j < arr.Length; j++)
        {
            if (arr[i] != arr[j])
            {
                arr[++i] = arr[j];
            }
        }
        return new string(arr, 0, i + 1);
    }
}
